\\[1ex] 2x^2 + 5x – 10 &= x^2 + x – 8 \:\mathrm{subtract\; them\; together} 
\\[1ex] x^2 + x - 10 + 8 &= 0 \:\mathrm{comparing\; both\; sides} 
\\[1ex] x^2 + x - 2 &= 0 \:\mathrm{factor} 
\\[1ex] x^2 + 2x - x - 2 &= 0 \:\mathrm{grouping\; terms} 
\\[1ex] x(x + 2) – 1(x + 2) &= 0 \:\mathrm{extract\; common\; factors} 
\\[1ex] (x - 1)(x + 2) &= 0 \:\mathrm{common\; factor\; extracted} 
\\[1ex] x &= 1,-2 
\end{align} \]
